// ===================== CONFIG — Aviso de O.S. nova (WhatsApp) =====================
// ENVIO: 'NENHUM'  -> só monta (confira o nó "Montar avisos")
//        'SIMULAR' -> manda até 3 avisos de amostra só para TESTE_PARA (não marca nada como avisado)
//        'REAL'    -> manda para os técnicos e marca as O.S. como avisadas (não avisa de novo)
const ENVIO = 'REAL';
const TESTE_PARA = '55__TELEFONE__';      // recebe as amostras no modo SIMULAR
const WAHA_SESSION = 'session_01m4xy9khpbqgnafzqhd9wchx1';

const MINUTOS_APOS_ABERTURA = 10;   // avisa a O.S. depois de N minutos da abertura
const JANELA_DIAS = 2;   // igual ao DIAS_SEM_REGISTRO do lembrete: mais velha que isso fica só com o lembrete
const HORA_INICIO = 10, HORA_FIM = 18;   // só envia entre 10:00 e 17:59
const DIAS_SEMANA = [1, 2, 3, 4, 5, 6];  // 1 = segunda ... 6 = sábado
const STATUS_AVISO = ['A', 'EN', 'AG', 'AN'];   // O.S. em execução/deslocamento não geram aviso
const MAX_POR_EXECUCAO = 10;        // máx. de técnicos avisados por rodada (o resto vai na próxima)
const MAX_MENSAGENS_DIA = 60;       // trava de segurança anti-bloqueio

// Mesmos assuntos do lembrete diário (ativação ×5 + documentação + Ativação T.I Resolutto)
const ASSUNTOS = {
  RESOLUTTO: [69, 83, 84, 86, 94, 85, 30],
  '4B':      [89, 90, 91, 93, 98, 92, 86],
  PONTO:     [65, 63, 62, 61, 70, 64, 52],
  CACTA:     [73, 74, 77, 75, 81, 76, 68],
  BUZZ:      [83, 84, 85, 87, 91, 86, 80],
};

// Pessoa -> WhatsApp e id de colaborador EM CADA BASE (ids mudam por base).
// whatsapp vazio = não recebe (aparece no resumo como "sem WhatsApp").
const PESSOAS = [
  { nome: 'Técnico 6',            whatsapp: '',             ids: { RESOLUTTO: [6],  CACTA: [6] } },
  { nome: 'Técnico 12',           whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [12], '4B': [12] } },
  { nome: 'Técnico 13',                     whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [13], CACTA: [13] } },
  { nome: 'Técnico 16',        whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [16], '4B': [16] } },
  { nome: 'Técnico 17',          whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [17], PONTO: [17] } },
  { nome: 'Técnico 18',       whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [18], '4B': [18] } },
  { nome: 'Técnico 20',          whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [20], PONTO: [20] } },
//  { nome: 'Técnico 21',                    whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [21], PONTO: [21] } },
  { nome: 'Técnico 22',         whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [22], '4B': [22], PONTO: [22], CACTA: [22], BUZZ: [22] } },
  { nome: 'Técnico 25',             whatsapp: '55__TELEFONE__',           ids: { RESOLUTTO: [25], '4B': [25] } },
  { nome: 'Técnico 31',            whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [31], CACTA: [31] } },
  { nome: 'Técnico 56',             whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [56], PONTO: [62] } },
  { nome: 'Técnico 52',           whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [52], '4B': [46], PONTO: [52], CACTA: [62], BUZZ: [58] } },
  { nome: 'Técnico 32',          whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [32], CACTA: [32] } },
  { nome: 'Técnico 54',            whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [54], CACTA: [46] } },
  { nome: 'Técnico 51',       whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [51], '4B': [61], PONTO: [59], CACTA: [49], BUZZ: [60] } },
  { nome: 'Técnico 35',                  whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [35], CACTA: [35] } },
  { nome: 'Técnico 37',         whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [37], PONTO: [37] } },
  { nome: 'Técnico 55',     whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [55], '4B': [48] } },
  { nome: 'Técnico 38', whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [38], CACTA: [38] } },
  { nome: 'Técnico 48',             whatsapp: '',             ids: { RESOLUTTO: [48] } },
  { nome: 'Técnico 57',           whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [57], BUZZ: [46] } },
  { nome: 'Técnico 41',   whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [41], '4B': [41] } },
  { nome: 'Técnico 42',             whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [42], '4B': [42], PONTO: [42], CACTA: [42], BUZZ: [42] } },
  { nome: 'Técnico PONTO-61',    whatsapp: '55__TELEFONE__', ids: { PONTO: [61] } },
  { nome: 'Técnico 43',         whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [43], '4B': [43], PONTO: [43], CACTA: [43], BUZZ: [43] } },
  { nome: 'Técnico 44',   whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [44], CACTA: [44] } }, // RESOLUTTO 44 marcado com (?) na lista
  { nome: 'Técnico 45',    whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [45], '4B': [45] } },
];
// =====================================================================================

const BASES = ['RESOLUTTO', '4B', 'PONTO', 'CACTA', 'BUZZ'];
const agora = DateTime.now().setZone('America/Sao_Paulo');
const erros = [];
const visto = {};
for (const p of PESSOAS) {
  for (const [b, ids] of Object.entries(p.ids)) {
    if (!BASES.includes(b)) erros.push(`${p.nome}: base desconhecida ${b}`);
    for (const id of ids) { const k = `${b}:${id}`; if (visto[k]) erros.push(`id ${id} da base ${b} aparece em ${visto[k]} e ${p.nome}`); visto[k] = p.nome; }
  }
  if (p.whatsapp && !/^55\d{10,11}$/.test(p.whatsapp)) erros.push(`${p.nome}: WhatsApp inválido ${p.whatsapp}`);
}
if (!['NENHUM', 'SIMULAR', 'REAL'].includes(ENVIO)) erros.push(`ENVIO inválido: ${ENVIO}`);
if (ENVIO === 'SIMULAR' && !/^55\d{10,11}$/.test(TESTE_PARA)) erros.push('ENVIO SIMULAR exige TESTE_PARA válido');
for (const b of BASES) if (!Array.isArray(ASSUNTOS[b]) || !ASSUNTOS[b].length) erros.push(`ASSUNTOS sem a base ${b}`);
if (erros.length) throw new Error('Config inválida: ' + erros.join(' | '));

const cfg = {
  ENVIO, TESTE_PARA, WAHA_SESSION, MINUTOS_APOS_ABERTURA, JANELA_DIAS, HORA_INICIO, HORA_FIM, DIAS_SEMANA,
  STATUS_AVISO, MAX_POR_EXECUCAO, MAX_MENSAGENS_DIA, ASSUNTOS, PESSOAS, BASES,
  JANELA_INICIO: agora.minus({ days: JANELA_DIAS }).toFormat('yyyy-MM-dd HH:mm:ss'),
  CORTE: agora.minus({ minutes: MINUTOS_APOS_ABERTURA }).toFormat('yyyy-MM-dd HH:mm:ss'),
  HOJE: agora.toFormat('yyyy-MM-dd'), AGORA: agora.toFormat('dd/MM HH:mm'),
};
return [{ json: { cfg } }];

function parse(item) {
  const j = (item && item.json) || {};
  if (j.error) return { erro: String(j.error.message || j.error) };
  let d = j.data !== undefined ? j.data : j;
  if (typeof d === 'string') {
    try { d = JSON.parse(d.replace(/[\u0000-\u001F]+/g, ' ')); }
    catch (e) { return { erro: 'resposta não é JSON: ' + d.slice(0, 120) }; }
  }
  if (d && d.type === 'error') return { erro: String(d.message || 'erro da API') };
  return { total: Number(d.total || 0), registros: Array.isArray(d.registros) ? d.registros : [] };
}
// Escolhe as O.S. novas ainda não avisadas (chave base:O.S.:técnico; se trocar o técnico, o novo é avisado)
const cfg = $('Config').first().json.cfg;
const sd = $getWorkflowStaticData('global');
const real = cfg.ENVIO === 'REAL';
const enviados = sd.enviados || {};
const dataValida = s => !!(s && s.length >= 10 && !s.startsWith('0000'));
let cands = [];
const erros = {}, avisos = [];
for (const base of cfg.BASES) {
  const r = parse($(`OS ${base}`).first());
  if (r.erro) { erros[base] = r.erro; continue; }
  if (r.total > r.registros.length) avisos.push(`${base}: ${r.total} O.S. na janela, lidas ${r.registros.length} (aumentar rp)`);
  const assuntos = cfg.ASSUNTOS[base].map(String);
  for (const o of r.registros) {
    const tec = String(o.id_tecnico || '0');
    if (tec === '0' || !cfg.STATUS_AVISO.includes(o.status) || !assuntos.includes(String(o.id_assunto))) continue;
    if (!dataValida(o.data_abertura) || o.data_abertura < cfg.JANELA_INICIO || o.data_abertura > cfg.CORTE) continue;
    const chave = `${base}:${o.id}:${tec}`;
    if (enviados[chave]) continue;
    cands.push({ chave, base, os: String(o.id), tec, status: o.status, id_assunto: String(o.id_assunto), id_cliente: String(o.id_cliente || ''), abertura: o.data_abertura, agenda: o.data_agenda || '' });
  }
}
// 1ª execução REAL: marca o que já existe como avisado, sem enviar (não dispara aviso de O.S. antiga)
let linhaDeBase = 0;
if (real && !sd.inicio) {
  sd.enviados = enviados;
  for (const c of cands) enviados[c.chave] = 'linha-de-base';
  sd.inicio = cfg.HOJE; linhaDeBase = cands.length; cands = [];
}
const ids = {};
for (const b of cfg.BASES) ids[b] = [...new Set(cands.filter(c => c.base === b && c.id_cliente && c.id_cliente !== '0').map(c => c.id_cliente))].slice(0, 100);
const n = Math.max(1, ...Object.values(ids).map(a => a.length));
return Array.from({ length: n }, (_, i) => ({ json: { i, ...(i === 0 ? { ids, cands, erros, avisos, linhaDeBase } : {}) } }));

// Monta 1 aviso por técnico com as O.S. novas dele (todas as bases juntas).
// ===== AUSÊNCIAS (férias, folga, atestado...) — quem estiver aqui NÃO recebe aviso =====
// pessoa: nome como está em PESSOAS (pode ser o começo do nome, se for único: 'Técnico 42')
// de / ate: AAAA-MM-DD ou DD/MM/AAAA (os dois dias entram). Sem 'ate' = até alguém tirar da lista.
const AUSENCIAS = [
  // { pessoa: 'Técnico 42', de: '20/10/2026', ate: '03/11/2026', motivo: 'Férias' },
  // { pessoa: 'Técnico 17', de: '17/10/2026', ate: '17/10/2026', motivo: 'Folga' },
];
const cfg = $('Config').first().json.cfg;
const { BASES, PESSOAS } = cfg;
const sel = $('Selecionar novas').first().json;
const sd = $getWorkflowStaticData('global');
const agora = DateTime.now().setZone('America/Sao_Paulo');
const STATUS_NOME = { A: 'Aberta', EN: 'Encaminhada', AG: 'Agendada', AN: 'Em análise' };
const dataValida = s => !!(s && s.length >= 10 && !s.startsWith('0000'));
const fmtDH = s => dataValida(s) ? `${s.slice(8, 10)}/${s.slice(5, 7)} ${s.slice(11, 16)}` : '?';
// ===== Escala (planilha "Quem trabalha hoje") =====
// Só as pessoas abaixo dependem da escala; as demais recebem sempre.
// chaves = como o nome aparece na planilha (sem acento, maiúsculas, palavra inteira).
const ESCALA = [
  { pessoa: 'Técnico 25',             chaves: ['Técnico 25'] },          // PALLADIUM CURITIBA - Técnico 25
  { pessoa: 'Técnico 18',       chaves: ['Técnico 18'] },       // PALLADIUM CURITIBA - Técnico 18
  { pessoa: 'Técnico 32',          chaves: ['Técnico 32'] },   // JOCKEY - Técnico 32
  { pessoa: 'Técnico 54',            chaves: ['Técnico 54'] },       // JOCKEY - Técnico 54
  { pessoa: 'Técnico 45',    chaves: ['Técnico 45'] },          // FOZ - Técnico 45
  { pessoa: 'Técnico 55',     chaves: ['Técnico 55'] },          // FOZ - Técnico 55
  { pessoa: 'Técnico 31',            chaves: ['Técnico 31'] }, // CASCAVEL - Técnico 31
  { pessoa: 'Técnico 38', chaves: ['Técnico 38'] },        // CASCAVEL - Técnico 38
  { pessoa: 'Técnico 21',                    chaves: ['Técnico 21'] },        // quadro Porto Belo e Tijucas
  { pessoa: 'Técnico 56',             chaves: ['Técnico 56'] },    // quadro Porto Belo e Tijucas
];
const norm = t => String(t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
function parseCSV(txt) {
  const rows = []; let row = [], cell = '', q = false;
  for (let i = 0; i < txt.length; i++) {
    const c = txt[i];
    if (q) { if (c === '"') { if (txt[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && txt[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
  return rows;
}
// Lê a planilha: devolve { ok, trabalhando: Set(pessoa), detalhe } — ok=false se não der para confiar nela
function lerEscala() {
  const it = $('Escala').first();
  const j = (it && it.json) || {};
  if (j.error) return { ok: false, detalhe: 'planilha não lida: ' + (j.error.message || j.error) };
  const txt = typeof j.data === 'string' ? j.data : '';
  if (!txt || /<html/i.test(txt.slice(0, 200))) return { ok: false, detalhe: 'planilha não lida (link CSV inválido ou não publicado)' };
  const g = parseCSV(txt);
  const acha = re => { for (let r = 0; r < g.length; r++) for (let c = 0; c < g[r].length; c++) if (re.test(norm(g[r][c]))) return [r, c]; return null; };
  const pos = acha(/QUEM TRABALHA HOJE/);
  if (!pos) return { ok: false, detalhe: 'planilha sem o quadro "QUEM TRABALHA HOJE"' };
  const [r0, c0] = pos;
  let data = null;
  for (let c = c0; c < Math.min(c0 + 4, g[r0].length); c++) { const m = norm(g[r0][c]).match(/(\d{1,2})\/(\d{1,2})/); if (m) { data = m[1].padStart(2, '0') + '/' + m[2].padStart(2, '0'); break; } }
  const hoje = DateTime.now().setZone('America/Sao_Paulo').toFormat('dd/MM');
  if (data !== hoje) return { ok: false, detalhe: `planilha desatualizada: "Quem trabalha hoje" está com data ${data || '(sem data)'}, hoje é ${hoje}` };
  const linhas = [];
  for (let r = r0 + 1; r < Math.min(r0 + 20, g.length); r++) { const v = norm(g[r][c0]); if (!v) { if (linhas.length) break; else continue; } if (/QUEM TRABALHA/.test(v)) break; linhas.push(v); }
  const pb = acha(/HOJE EM PORTO BELO/);
  let portoBelo = '';
  if (pb) for (let r = pb[0] + 1; r < Math.min(pb[0] + 4, g.length); r++) { const v = norm(g[r][pb[1]]); if (v) { portoBelo = v; break; } }
  const texto = ' ' + [...linhas, portoBelo].join(' | ') + ' ';
  const trabalhando = new Set(ESCALA.filter(e => e.chaves.some(k => new RegExp(`[^A-Z]${norm(k)}[^A-Z]`).test(texto))).map(e => e.pessoa));
  return { ok: true, trabalhando, detalhe: `escala ${data}: ${linhas.join(' / ')}${portoBelo ? ' / Porto Belo e Tijucas: ' + portoBelo : ' / (quadro Porto Belo e Tijucas não encontrado)'}` };
}

const LINKS = {
  RESOLUTTO: 'https://ixc.resolutto.com.br/app/login',
  '4B':      'https://ixc.4btelecom.com.br/app/login',
  PONTO:     'https://ixc.pontotelecom.com/app/login',
  CACTA:     'https://ixc.cactatelecom.com.br/app/login',
  BUZZ:      'https://ixc.buzztelecom.com.br/app/login',
};

function parse(item) {
  const j = (item && item.json) || {};
  if (j.error) return { erro: String(j.error.message || j.error) };
  let d = j.data !== undefined ? j.data : j;
  if (typeof d === 'string') {
    try { d = JSON.parse(d.replace(/[\u0000-\u001F]+/g, ' ')); }
    catch (e) { return { erro: 'resposta não é JSON: ' + d.slice(0, 120) }; }
  }
  if (d && d.type === 'error') return { erro: String(d.message || 'erro da API') };
  return { total: Number(d.total || 0), registros: Array.isArray(d.registros) ? d.registros : [] };
}

const panorama = { candidatas: (sel.cands || []).length, linha_de_base: sel.linhaDeBase || 0, erros: sel.erros || {}, avisos: [...(sel.avisos || [])] };

// nomes de assunto e cliente
const nomeAssunto = {}, nomeCliente = {};
for (const base of BASES) {
  nomeAssunto[base] = {}; nomeCliente[base] = {};
  const ra = parse($(`Assuntos ${base}`).first());
  (ra.registros || []).forEach(a => nomeAssunto[base][String(a.id)] = a.assunto || a.descricao);
  if (ra.erro) panorama.avisos.push(`${base}: nomes de assunto não lidos (${ra.erro})`);
  try { $(`Cliente ${base}`).all().forEach(it => { const c = (parse(it).registros || [])[0]; if (c && c.id) nomeCliente[base][String(c.id)] = String(c.fantasia || c.razao || '').trim(); }); } catch (e) {}
}

// ausências de hoje
const hojeISO = agora.toFormat('yyyy-MM-dd');
const dataISO = v => { const t = String(v || '').trim(); let m, iso = null;
  if ((m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/))) iso = t;
  else if ((m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/))) iso = `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return iso && DateTime.fromISO(iso).isValid ? iso : null; };
const ausentesHoje = new Map();
for (const a of AUSENCIAS) {
  const alvo = norm(a.pessoa);
  const achados = PESSOAS.filter(p => norm(p.nome) === alvo || norm(p.nome).startsWith(alvo + ' '));
  if (!alvo || achados.length !== 1) { panorama.avisos.push(`AUSENCIAS: "${a.pessoa}" ${achados.length ? 'ambíguo' : 'não encontrado'}`); continue; }
  const de = dataISO(a.de), ate = a.ate ? dataISO(a.ate) : null;
  if (!de || (a.ate && !ate)) { ausentesHoje.set(achados[0].nome, (a.motivo || 'Ausente') + ' (data inválida)'); continue; }
  if (hojeISO >= de && (!ate || hojeISO <= ate)) ausentesHoje.set(achados[0].nome, a.motivo || 'Ausente');
}

const escala = lerEscala();
const deEscala = new Set(ESCALA.map(e => e.pessoa));
panorama.escala = { ok: escala.ok, detalhe: escala.detalhe };

const porId = {};
for (const p of PESSOAS) for (const [b, ids] of Object.entries(p.ids)) for (const id of ids) porId[`${b}:${id}`] = p;

const porPessoa = new Map(), espera = [], semWhats = [];
for (const c of (sel.cands || [])) {
  const p = porId[`${c.base}:${c.tec}`];
  if (!p || !p.whatsapp) { semWhats.push(`${p ? p.nome : 'id ' + c.tec} (${c.base} O.S. ${c.os})`); continue; }
  if (ausentesHoje.has(p.nome)) { espera.push(`${p.nome} – O.S. ${c.os} (${ausentesHoje.get(p.nome)})`); continue; }
  if (deEscala.has(p.nome) && (!escala.ok || !escala.trabalhando.has(p.nome))) { espera.push(`${p.nome} – O.S. ${c.os} (${escala.ok ? 'folga na escala' : 'escala com problema'})`); continue; }
  if (!porPessoa.has(p)) porPessoa.set(p, []);
  porPessoa.get(p).push(c);
}
panorama.em_espera = espera;
panorama.sem_whatsapp = semWhats;

const envios = [];
for (const [p, lista] of porPessoa) {
  lista.sort((a, b) => a.abertura.localeCompare(b.abertura));
  const n = lista.length;
  const linhas = lista.map(c => {
    const cli = nomeCliente[c.base][c.id_cliente] || ('cliente ' + c.id_cliente);
    const ag = c.status === 'AG' && dataValida(c.agenda) ? ` · agendada p/ ${fmtDH(c.agenda)}` : '';
    return `• *${c.base}* · O.S. ${c.os} · ${cli.length > 45 ? cli.slice(0, 44) + '…' : cli} · ${nomeAssunto[c.base][c.id_assunto] || 'assunto ' + c.id_assunto} · aberta ${fmtDH(c.abertura)}${ag}`;
  });
  const links = [...new Set(lista.map(c => c.base))].map(b => LINKS[b]).filter(Boolean);
  const texto = [
    `Olá, ${p.nome.split(' ')[0]}!`,
    n === 1 ? 'Você recebeu *1 nova O.S.*:' : `Você recebeu *${n} novas O.S.*:`,
    '',
    ...linhas,
    '',
    'Registre o andamento e use o botão *Agendar* no IXC.',
    '',
    links.length === 1 ? 'Link de acesso da base:' : 'Links de acesso das bases:',
    ...links,
    '',
    '_Aviso automático – Resolutto_',
  ].join('\n');
  envios.push({ tipo: 'nova', nome: p.nome, telefone: p.whatsapp, qtd: n, chaves: lista.map(c => c.chave), texto });
}

// horário, limites e marcação
const dentroHorario = cfg.DIAS_SEMANA.includes(agora.weekday) && agora.hour >= cfg.HORA_INICIO && agora.hour < cfg.HORA_FIM;
const jaHoje = (sd.contagem || {})[cfg.HOJE] || 0;
let motivo = null, fila = [];
if (cfg.ENVIO === 'NENHUM') motivo = 'ENVIO = NENHUM (só montagem)';
else if (!dentroHorario) motivo = `fora do horário (${cfg.HORA_INICIO}h–${cfg.HORA_FIM}h, seg–sáb) — fica para a próxima rodada no horário`;
else if (cfg.ENVIO === 'SIMULAR') fila = envios.slice(0, 3).map(e => ({ ...e, telefone: cfg.TESTE_PARA, texto: `[SIMULAÇÃO → ${e.nome} ${e.telefone}]\n\n${e.texto}` }));
else {
  const cabe = Math.max(0, Math.min(cfg.MAX_POR_EXECUCAO, cfg.MAX_MENSAGENS_DIA - jaHoje));
  fila = envios.slice(0, cabe);
  if (envios.length > fila.length) panorama.avisos.push(`${envios.length - fila.length} aviso(s) ficaram para a próxima rodada (limite por rodada/dia)`);
  sd.enviados = sd.enviados || {};
  for (const e of fila) for (const k of e.chaves) sd.enviados[k] = cfg.HOJE;
  sd.contagem = { [cfg.HOJE]: jaHoje + fila.length };
  // limpeza: esquece marcações antigas
  const limite = agora.minus({ days: cfg.JANELA_DIAS + 5 }).toFormat('yyyy-MM-dd');
  for (const [k, v] of Object.entries(sd.enviados)) if (v !== 'linha-de-base' && v < limite) delete sd.enviados[k];
}

return [
  { json: { tipo: 'panorama', enviar: false, envio: cfg.ENVIO, motivo_sem_envio: motivo, avisos_montados: envios.length, enviados_hoje_antes: jaHoje, ...panorama } },
  ...envios.map(e => ({ json: { ...e, enviar: false } })),
  ...fila.map(e => ({ json: { ...e, enviar: true } })),
];
